<template><div class="resource-manager"><WorkspaceHero eyebrow="SOURCE & PUBLICATION" title="制度与活动发布" description="先保存草稿、核对来源，再发布给适用学生。已发布内容通过修订版更新，保留原文与历史版本。"><template #actions><el-button type="primary" :disabled="!collegeId" @click="createNew">新建{{kind==='policy'?'制度':'活动'}}草稿</el-button></template></WorkspaceHero>
  <section class="card resource-toolbar"><el-radio-group v-model="kind" aria-label="资源类型" @change="changeFilter"><el-radio-button label="policy">制度原文</el-radio-button><el-radio-button label="activity">校园活动</el-radio-button></el-radio-group><el-select v-if="user.role!=='college_admin'" v-model="collegeId" aria-label="发布院系" placeholder="选择发布院系" @change="changeFilter"><el-option v-for="college in colleges" :key="college.id" :label="college.name" :value="college.id"/></el-select><el-button :loading="loading" @click="load">刷新清单</el-button><span>发布范围：所选院系内符合年级与专业条件的学生</span></section>
  <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><el-alert v-if="limited" title="当前最多展示最近 200 个版本，可切换资源类型或院系查看。" type="info" :closable="false"/>
  <section class="card resource-list" v-loading="loading"><el-table :data="rows" stripe empty-text="暂无资源，请先新建草稿并录入来源原文。"><el-table-column prop="data.title" label="标题" min-width="220"/><el-table-column prop="data.academicYear" label="适用学年" width="125"/><el-table-column label="版本" width="80"><template #default="{row}">v{{row.revision}}</template></el-table-column><el-table-column label="状态" width="140"><template #default="{row}"><el-tag :type="row.status==='published'?'success':row.status==='draft'?'warning':'info'">{{statusLabels[row.status]}}</el-tag></template></el-table-column><el-table-column prop="data.issuer" label="发布单位" min-width="150"/><el-table-column label="操作" min-width="250"><template #default="{row}"><el-button link type="primary" @click="openEditor(row)">{{row.status==='draft'?'编辑与发布':'查看原文'}}</el-button><el-button v-if="row.status!=='draft'" link type="primary" :disabled="!!busy" @click="revise(row)">创建修订版</el-button><el-button v-if="row.status==='published'" link type="warning" :disabled="!!busy" @click="withdraw(row)">撤回发布</el-button></template></el-table-column></el-table></section>
  <el-dialog v-model="visible" :title="editor?.status==='draft'||!editor?'编辑发布草稿':'查看已发布版本'" width="min(960px,96vw)" :close-on-click-modal="false" @closed="closeEditor"><p class="resource-note">{{readOnly?'此版本正文不可覆盖。需要修改时请返回清单创建修订版。':'保存草稿不会向学生展示；勾选来源核对后才可发布。'}}{{editor?` 当前 v${editor.revision}。`:''}}</p>
    <el-form label-position="top" :disabled="readOnly||!!busy" class="resource-form"><el-form-item label="标题"><el-input v-model="form.title" maxlength="160" show-word-limit/></el-form-item><el-form-item label="适用学年"><el-select v-model="form.academicYear"><el-option v-for="y in years" :key="y" :label="y" :value="y"/></el-select></el-form-item><el-form-item label="发布单位"><el-input v-model="form.issuer" maxlength="100" placeholder="按来源通知填写学校或主办单位"/></el-form-item><el-form-item label="来源链接（HTTPS）"><el-input v-model="form.sourceUrl" maxlength="1000" placeholder="原制度或活动通知的链接"/></el-form-item><el-form-item label="适用年级（留空为本院系全部年级）"><el-select v-model="form.grades" multiple filterable allow-create default-first-option placeholder="输入年级后确认"/></el-form-item><el-form-item label="适用专业（留空为本院系全部专业）"><el-select v-model="form.majors" multiple filterable allow-create default-first-option placeholder="输入专业名称后确认"/></el-form-item><el-form-item label="摘要" class="full-row"><el-input v-model="form.summary" type="textarea" :rows="2" maxlength="500" show-word-limit/></el-form-item>
    <template v-if="kind==='policy'"><el-form-item label="制度文号"><el-input v-model="form.referenceNo" maxlength="100"/></el-form-item><el-form-item label="生效日期"><el-date-picker v-model="form.effectiveFrom" type="date" value-format="YYYY-MM-DD" aria-label="制度生效日期"/></el-form-item><el-form-item label="失效日期（可留空）"><el-date-picker v-model="form.effectiveTo" type="date" value-format="YYYY-MM-DD" aria-label="制度失效日期" clearable/></el-form-item><el-form-item label="制度原文（按条款分段，空行分隔）" class="full-row"><el-input v-model="form.body" type="textarea" :rows="12" maxlength="40000" show-word-limit placeholder="粘贴已核对的原文，保留条款编号，不填写自行推测的分值。"/></el-form-item></template>
    <template v-else><el-form-item label="五育方向"><el-select v-model="form.focusKey"><el-option v-for="(label,key) in focus" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item label="预计时长（分钟）"><el-input-number v-model="form.durationMinutes" :min="15" :max="1440"/></el-form-item><el-form-item label="报名截止时间"><el-date-picker v-model="form.registrationEndAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" aria-label="活动报名截止时间"/></el-form-item><el-form-item label="活动开始时间"><el-date-picker v-model="form.startsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" aria-label="活动开始时间"/></el-form-item><el-form-item label="活动结束时间"><el-date-picker v-model="form.endsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" aria-label="活动结束时间"/></el-form-item><el-form-item label="活动地点"><el-input v-model="form.location" maxlength="200"/></el-form-item><el-form-item label="主办方报名链接（选填）"><el-input v-model="form.registrationUrl" maxlength="1000"/></el-form-item><el-form-item label="费用说明"><el-input v-model="form.costDescription" maxlength="200" placeholder="以来源通知为准，不确定时不要填免费"/></el-form-item><el-form-item label="活动标签"><el-select v-model="form.tags" multiple filterable allow-create default-first-option/></el-form-item><el-form-item label="完整活动说明" class="full-row"><el-input v-model="form.description" type="textarea" :rows="8" maxlength="10000" show-word-limit placeholder="填写参与要求、报名方式及活动安排，不承诺未确认的名额或加分。"/></el-form-item></template>
    </el-form><p v-if="editor?.withdrawalReason" class="resource-note">撤回原因：{{editor.withdrawalReason}}</p><el-checkbox v-if="!readOnly" v-model="sourceConfirmed" :disabled="!!busy">我已核对来源原文、发布单位、适用范围与日期</el-checkbox><el-alert v-if="editorError" :title="editorError" type="error" :closable="false" class="editor-error"/>
    <template #footer><el-button @click="visible=false" :disabled="!!busy">关闭</el-button><el-button v-if="!readOnly" :loading="busy==='save'" :disabled="!!busy" @click="save">保存草稿</el-button><el-button v-if="!readOnly" type="primary" :loading="busy==='publish'" :disabled="!!busy||!sourceConfirmed" @click="publish">保存并发布</el-button></template>
  </el-dialog>
</div></template>
<script setup>
import {ref,reactive,computed,watch,onMounted,onBeforeUnmount} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import WorkspaceHero from '@/components/WorkspaceHero.vue';import {useUserStore} from '@/stores/user';import {getCollegeList} from '@/api/college';import {getGuidanceResources,createGuidanceResource,saveGuidanceResource,reviseGuidanceResource,publishGuidanceResource,withdrawGuidanceResource} from '@/api/guidance';
const user=useUserStore();const kind=ref('policy');const collegeId=ref(user.userInfo?.collegeId||null);const colleges=ref([]);const rows=ref([]);const loading=ref(false);const error=ref('');const limited=ref(false);const visible=ref(false);const editor=ref(null);const editorError=ref('');const sourceConfirmed=ref(false);const busy=ref('');let version=0,editorVersion=0;
const start=new Date().getFullYear()-(new Date().getMonth()<8?1:0);const years=Array.from({length:6},(_,i)=>`${start+1-i}-${start+2-i}`);const focus={morality:'德育实践',academy:'学习与创新',sports:'体育健康',arts:'美育实践',labor:'劳动与志愿服务'};const statusLabels={draft:'草稿',published:'当前发布',superseded:'已被新版本替代',withdrawn:'已撤回'};
const fresh=()=>({title:'',academicYear:`${start}-${start+1}`,issuer:'',sourceUrl:'',grades:[],majors:[],summary:'',referenceNo:'',effectiveFrom:new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'}),effectiveTo:null,body:'',focusKey:'labor',durationMinutes:60,registrationEndAt:'',startsAt:'',endsAt:'',location:'',registrationUrl:'',costDescription:'以主办方通知为准',tags:[],description:''});const form=reactive(fresh());const readOnly=computed(()=>!!editor.value&&editor.value.status!=='draft');watch(form,()=>{sourceConfirmed.value=false;},{deep:true,flush:'sync'});
async function load(){const current=++version;loading.value=true;rows.value=[];error.value='';limited.value=false;if(!collegeId.value){loading.value=false;return;}try{const result=await getGuidanceResources({collegeId:collegeId.value,kind:kind.value});if(current===version){rows.value=result.items;limited.value=result.limited;}}catch(err){if(current===version)error.value=err.message||'清单读取失败，请刷新重试';}finally{if(current===version)loading.value=false;}}
function closeEditor(){editorVersion++;editor.value=null;editorError.value='';sourceConfirmed.value=false;}
function openEditor(row){editorVersion++;editor.value=JSON.parse(JSON.stringify(row));Object.assign(form,fresh(),JSON.parse(JSON.stringify(row.data)));editorError.value='';sourceConfirmed.value=false;visible.value=true;}
function createNew(){editorVersion++;editor.value=null;Object.assign(form,fresh());editorError.value='';sourceConfirmed.value=false;visible.value=true;}
function changeFilter(){visible.value=false;closeEditor();load();}
async function saveDraft(){const token=editorVersion;const payload=JSON.parse(JSON.stringify(form));const row=editor.value;const result=row?await saveGuidanceResource(row.id,{data:payload,editVersion:row.editVersion}):await createGuidanceResource({collegeId:collegeId.value,kind:kind.value,data:payload});if(token!==editorVersion)return null;editor.value=result;return result;}
async function save(){if(busy.value)return;busy.value='save';editorError.value='';try{const result=await saveDraft();if(result){ElMessage.success('草稿已保存，尚未向学生发布');await load();}}catch(err){editorError.value=err.message||'保存失败，请检查内容';}finally{busy.value='';}}
async function publish(){if(busy.value||!sourceConfirmed.value)return;busy.value='publish';editorError.value='';const token=editorVersion;try{const saved=await saveDraft();if(!saved||token!==editorVersion)return;const result=await publishGuidanceResource(saved.id,{editVersion:saved.editVersion,sourceConfirmed:true});if(token===editorVersion){editor.value=result;visible.value=false;ElMessage.success('已发布，适用学生可查看当前版本');await load();}}catch(err){if(token===editorVersion)editorError.value=err.message||'发布失败，请检查来源和日期';}finally{busy.value='';}}
async function revise(row){if(busy.value)return;busy.value='revise';const current=version;try{const result=await reviseGuidanceResource(row.id,{editVersion:row.editVersion});if(current===version){openEditor(result);await load();}}catch(err){ElMessage.error(err.message||'创建修订版失败');}finally{busy.value='';}}
async function withdraw(row){if(busy.value)return;try{const {value}=await ElMessageBox.prompt('撤回后学生不再看到此版本，历史引用仍保留版本标识。','撤回发布',{inputType:'textarea',inputPlaceholder:'填写撤回原因',inputValidator:value=>!!value&&value.trim().length>=2&&value.length<=500||'请输入 2–500 字原因',confirmButtonText:'撤回发布',cancelButtonText:'取消'});busy.value='withdraw';await withdrawGuidanceResource(row.id,{editVersion:row.editVersion,reason:value});ElMessage.success('已撤回发布');await load();}catch(err){if(err!=='cancel'&&err!=='close')ElMessage.error(err.message||'未能撤回，请刷新重试');}finally{busy.value='';}}
onMounted(async()=>{if(user.role!=='college_admin'){try{const result=await getCollegeList({pageSize:1000});colleges.value=result.list||result;if(!collegeId.value)collegeId.value=colleges.value[0]?.id||null;}catch(err){error.value=err.message||'院系列表读取失败';return;}}await load();});onBeforeUnmount(()=>{version++;editorVersion++;});
</script>
<style scoped>
.resource-toolbar{display:flex;align-items:center;gap:14px;flex-wrap:wrap;padding:20px;margin:20px 0;}.resource-toolbar>.el-select{width:220px;}.resource-toolbar>span,.resource-note{font-size:12px;line-height:1.9;color:#687d95;}.resource-toolbar>span{flex:1;}.resource-list{padding:16px;margin-top:18px;min-width:0;}.resource-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 20px;}.resource-form .el-select,.resource-form :deep(.el-date-editor){width:100%;}.full-row{grid-column:1/-1;}.editor-error{margin-top:16px;}.resource-manager :deep(.el-checkbox){white-space:normal;height:auto;}.resource-manager :deep(.el-checkbox__label){line-height:1.8;white-space:normal;}@media(max-width:650px){.resource-form{grid-template-columns:minmax(0,1fr);}.resource-toolbar>.el-select{width:100%;}.resource-toolbar>span{flex-basis:100%;}.resource-list{padding:8px;}}
</style>
